390	        if (sort.active === 'timestamp') {
391	          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
392	        }
393	        if (sort.active === '_checked') {
394	          const session1isChecked = this.isChecked(session1);
395	          const session2isChecked = this.isChecked(session2);
396	          if (!session1isChecked && session2isChecked) {
397	            return 1 * sortDirectionFactor;
398	          }
399	          if (session1isChecked && !session2isChecked) {
