418	        if (sort.active.startsWith('bookletState:')) {
419	          const bookletState = sort.active.replace('bookletState:', '');
420	          const label = (session: TestSession): string =>
421	            TestSessionUtil.bookletStateLabel(session, bookletState) ?? 'zzzzzzzzzz';
422	          const a = label(session1);
423	          const b = label(session2);
424	          return a.localeCompare(b) * sortDirectionFactor;
425	        }
426	        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
427	        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
428	        if (typeof valA === 'number') {
