583	        Object.values(isBooklet(session.booklet) ? session.booklet?.states : {})
584	          .forEach(state => {
585	            bookletStateLabels[state.id] = state.label;
586	          });
587	        if (TestSessionUtil.isPaused(session)) paused += 1;
588	        if (TestSessionUtil.isLocked(session)) locked += 1;
589	      });
590	
591	    return {
592	      numberOfSessions: sessionSet.length,
593	      differentBooklets: booklets.size,
594	      differentBookletSpecies: bookletSpecies.size,
595	      allChecked: (all === sessionSet.length),
596	      bookletStateLabels,
597	      pausedSessions: paused,
598	      lockedSessions: locked
