260	  getSessionColor(session: TestSession): string {
261	    const stripes = (c1: string, c2: string) => `repeating-linear-gradient(45deg, ${c1}, ${c1} 10px, ${c2} 10px, ${c2} 20px)`;
262	    const hsl = (h: number, s: number, l: number) => `hsl(${h}, ${s}%, ${l}%)`;
263	    const colorful = this.displayOptions.highlightSpecies && session.booklet.species;
264	    const h = colorful ? (
265	      session.booklet.species.length *
266	      session.booklet.species.charCodeAt(0) *
267	      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
268	      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
269	      session.booklet.species.charCodeAt(session.booklet.species.length / 2) *
270	      session.booklet.species.charCodeAt(3 * (session.booklet.species.length / 4)) *
271	      session.booklet.species.charCodeAt(session.booklet.species.length - 1)
272	    ) % 360 : 0;
273	
274	    switch (session.state) {
275	      case 'paused':
276	        return hsl(h, colorful ? 45 : 0, 90);
277	      case 'pending':
278	      case 'locked':
279	        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 0, 92));
280	      case 'error':
281	        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 30, 95));
282	      default:
283	        return hsl(h, colorful ? 75 : 0, colorful ? 95 : 100);
284	    }
285	  }
